SET SESSION sql_mode='STRICT_ALL_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_AUTO_CREATE_USER,NO_ENGINE_SUBSTITUTION,NO_ZERO_DATE,NO_ZERO_IN_DATE';
DELIMITER //
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_account_invitation_claim_next_v1(OUT p_disposition VARCHAR(16),OUT p_outbox_id CHAR(36),OUT p_attempt_id CHAR(36),OUT p_invitation_id CHAR(36),OUT p_payload MEDIUMBLOB) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_outbox CHAR(36); DECLARE v_invitation CHAR(36); DECLARE v_state VARCHAR(16); DECLARE v_status VARCHAR(16); DECLARE v_expires DATETIME(6); DECLARE v_payload MEDIUMBLOB; DECLARE v_attempt CHAR(36); DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account delivery transaction denied'; END IF; SET p_disposition='EMPTY',p_outbox_id=NULL,p_attempt_id=NULL,p_invitation_id=NULL,p_payload=NULL; SET TRANSACTION ISOLATION LEVEL READ COMMITTED; START TRANSACTION; SELECT outbox_id,invitation_id INTO v_outbox,v_invitation FROM office_account_invitation_outbox FORCE INDEX(idx_office_account_invitation_outbox_queue) WHERE state='QUEUED' ORDER BY created_at,outbox_id LIMIT 1; IF v_outbox IS NULL THEN COMMIT; LEAVE proc; END IF; SELECT status,expires_at INTO v_status,v_expires FROM office_account_invitation WHERE invitation_id=v_invitation FOR UPDATE; SELECT state,payload_ciphertext INTO v_state,v_payload FROM office_account_invitation_outbox WHERE outbox_id=v_outbox FOR UPDATE; IF v_state<>'QUEUED' THEN COMMIT; SET p_disposition='RETRY'; LEAVE proc; END IF; IF v_status<>'ISSUED' THEN ROLLBACK; SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account queued lifecycle denied'; END IF; IF v_expires<=UTC_TIMESTAMP(6) THEN COMMIT; SET p_disposition='DUE'; LEAVE proc; END IF; SET v_attempt=LOWER(UUID()); UPDATE office_account_invitation_outbox SET state='CLAIMED',attempt_id=v_attempt,attempt_count=1,claimed_at=UTC_TIMESTAMP(6) WHERE outbox_id=v_outbox AND state='QUEUED'; IF ROW_COUNT()<>1 THEN ROLLBACK; SET p_disposition='RETRY'; LEAVE proc; END IF; COMMIT; SET p_disposition='CLAIMED',p_outbox_id=v_outbox,p_attempt_id=v_attempt,p_invitation_id=v_invitation,p_payload=v_payload; END//
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_account_invitation_expire_due_v1(IN p_limit SMALLINT UNSIGNED,OUT p_expired SMALLINT UNSIGNED) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_invitation CHAR(36); DECLARE v_done BOOL DEFAULT FALSE; DECLARE due_cursor CURSOR FOR SELECT invitation_id FROM office_account_invitation FORCE INDEX(idx_office_account_invitation_live) WHERE status='ISSUED' AND expires_at<=UTC_TIMESTAMP(6) ORDER BY expires_at,invitation_id LIMIT p_limit; DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=TRUE; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 OR p_limit IS NULL OR p_limit<1 OR p_limit>100 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account expiry input denied'; END IF; SET p_expired=0; OPEN due_cursor; expiry_loop: LOOP FETCH due_cursor INTO v_invitation; IF v_done THEN LEAVE expiry_loop; END IF; START TRANSACTION; UPDATE office_account_invitation SET status='EXPIRED',version=version+1 WHERE invitation_id=v_invitation AND status='ISSUED' AND expires_at<=UTC_TIMESTAMP(6); IF ROW_COUNT()=1 THEN UPDATE office_account_invitation_outbox SET state='CANCELLED',attempt_id=LOWER(UUID()),attempt_count=1,payload_ciphertext=NULL,finished_at=UTC_TIMESTAMP(6) WHERE invitation_id=v_invitation AND state='QUEUED'; SET p_expired=p_expired+1; END IF; COMMIT; END LOOP; CLOSE due_cursor; END//
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_account_invitation_settle_delivery_v1(IN p_outbox_id CHAR(36),IN p_attempt_id CHAR(36),IN p_result VARCHAR(16),IN p_message_id VARCHAR(320),OUT p_disposition VARCHAR(16)) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_state VARCHAR(16); DECLARE v_attempt CHAR(36); DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 OR p_outbox_id NOT REGEXP '^[0-9a-f-]{36}$' OR p_attempt_id NOT REGEXP '^[0-9a-f-]{36}$' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account settle identity denied'; END IF; IF p_result='SMTP_ACCEPTED' THEN IF p_message_id IS NULL OR p_message_id='' OR CHAR_LENGTH(p_message_id)>320 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account accepted receipt denied'; END IF; ELSEIF p_result IN ('SMTP_UNKNOWN','SMTP_STALE') THEN IF p_message_id IS NOT NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account unknown receipt denied'; END IF; ELSE SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account settle result denied'; END IF; SET p_disposition='FENCED'; START TRANSACTION; SELECT state,attempt_id INTO v_state,v_attempt FROM office_account_invitation_outbox WHERE outbox_id=p_outbox_id FOR UPDATE; IF v_attempt<>p_attempt_id THEN COMMIT; LEAVE proc; END IF; IF v_state<>'CLAIMED' THEN IF (v_state='SMTP_ACCEPTED' AND p_result='SMTP_ACCEPTED') OR (v_state='UNKNOWN' AND p_result='SMTP_UNKNOWN') THEN SET p_disposition='REPLAYED'; END IF; COMMIT; LEAVE proc; END IF; UPDATE office_account_invitation_outbox SET state=IF(p_result='SMTP_ACCEPTED','SMTP_ACCEPTED','UNKNOWN'),payload_ciphertext=NULL,message_id=IF(p_result='SMTP_ACCEPTED',p_message_id,NULL),result_code=p_result,finished_at=UTC_TIMESTAMP(6) WHERE outbox_id=p_outbox_id; COMMIT; SET p_disposition='APPLIED'; END//
CREATE DEFINER=`jaxoffice_invitation_owner`@`localhost` PROCEDURE office_account_invitation_settle_stale_v1(IN p_timeout SMALLINT UNSIGNED,IN p_limit SMALLINT UNSIGNED,OUT p_settled SMALLINT UNSIGNED) SQL SECURITY DEFINER MODIFIES SQL DATA proc: BEGIN DECLARE v_outbox CHAR(36); DECLARE v_done BOOL DEFAULT FALSE; DECLARE stale_cursor CURSOR FOR SELECT outbox_id FROM office_account_invitation_outbox WHERE state='CLAIMED' AND claimed_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL p_timeout SECOND) ORDER BY claimed_at,outbox_id LIMIT p_limit; DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=TRUE; DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END; IF @@in_transaction<>0 OR p_timeout IS NULL OR p_timeout<1 OR p_timeout>3600 OR p_limit IS NULL OR p_limit<1 OR p_limit>1000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='office account stale input denied'; END IF; SET p_settled=0; OPEN stale_cursor; stale_loop: LOOP FETCH stale_cursor INTO v_outbox; IF v_done THEN LEAVE stale_loop; END IF; START TRANSACTION; UPDATE office_account_invitation_outbox SET state='UNKNOWN',payload_ciphertext=NULL,result_code='SMTP_STALE',finished_at=UTC_TIMESTAMP(6) WHERE outbox_id=v_outbox AND state='CLAIMED' AND claimed_at<DATE_SUB(UTC_TIMESTAMP(6),INTERVAL p_timeout SECOND); IF ROW_COUNT()=1 THEN SET p_settled=p_settled+1; END IF; COMMIT; END LOOP; CLOSE stale_cursor; END//
DELIMITER ;
